from gf import *
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_amb_op1.csv','train/A_vref_op3.csv']
D={f:load(f) for f in files}
def simq(p,d,dt=0.001):
    G,H,tau,K2,tauv=p
    V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; th=d.bus_angle_rad.values
    Q=d.reactive_power_pu.values; P=d.active_power_pu.values
    n=len(V); q=Q[0]; Vf=V[0]; Qo=np.empty(n)
    Q0=Q[0]; V0=V[0]
    for k in range(n):
        Qo[k]=q
        tgt=Q0+G*(Vs[k]-1.0)-H*(V[k]-V0)
        q+=dt*(tgt-q)/tau
    return Qo
def res(p,keys):
    return np.concatenate([simq(p,D[f])-D[f].reactive_power_pu.values for f in keys])
for p0 in [[5,20,0.02,0,0.01]]:
    s=least_squares(res,p0,args=(files,),bounds=([0,0,0.001,0,0],[50,100,1,1,1]),diff_step=1e-3)
    print(s.x, np.sqrt(np.mean(s.fun**2)))
    for f in files: print(f,np.sqrt(np.mean(res(s.x,[f])**2)))

